#pragma once
#include "commerce_details.hpp"
namespace perekup {
inline Json nativeCommerceVehicleDocuments(const Json& s,const Json& car,const Json& offers,const std::string& home){auto v=contractDocumentIds(car.at("id"),car.value("cityId",home)==home);v["name"]=car.value("name","");v["description"]=car.value("desc","");std::smatch match;auto name=car.value("name","");v["year"]=std::regex_search(name,match,std::regex("(?:19|20)[0-9]{2}"))?std::stoi(match.str()):0;auto color=nativeFactoryColorInfo(nativeFactoryColor(s,car,offers));v["color"]=color?color->name:"Серебристый";return v;}
inline bool appendNativeSupplyContract(Json& s,const Json& o,const Json& offer,const Json& car,const Json& cities,const Json& offers,const std::string& home,bool recovered=false){auto& b=s["contracts"];auto id="purchase-"+o.at("id").get<std::string>();for(const auto& record:b["records"])if(record.value("id","")==id)return false;bool imported=offer.value("kind","")=="import";auto costs=o.at("costs");costs.erase("storage");Money total=commerceTotal(costs);Json seller={{"fullName",offer.value("seller","")},{"passport","Организация · игровой поставщик"},{"address",imported?offer.value("country",""):std::string("г. Москва")}};seller["signature"]=Json::parse(R"([[[0.1,0.7],[0.25,0.25],[0.32,0.7],[0.6,0.3],[0.8,0.6]]])");Money seq=Money(num(b,"sequence"))+1;b["sequence"]=seq;auto number=std::to_string(seq);if(number.size()<5)number=std::string(5-number.size(),'0')+number;
 std::string terms=imported?"Стоимость валюты и доставки зафиксирована. Выкуп и перевозка оплачиваются при заказе, оформление — после прибытия на таможню. Три дня хранения бесплатны, далее 2 000 ₽ за начатый игровой день. Экспорт — 2 дня, перевозка — "+std::to_string(int(num(offer,"days")))+" дней, оформление — 2 дня, доставка по России — 3 дня. Оформление выполняет посредник для последующей продажи автомобиля.":"Автомобиль из наличия. Передача выполняется после осмотра и подписания акта приёма-передачи. "+offer.value("report","");Money paid=imported?Money(num(costs,"vehicle")+num(costs,"transfer")+num(costs,"delivery")+num(costs,"inspection")):total;
 Json record={{"version",1},{"id",id},{"number","ПОСТ-"+number},{"mode","buy"},{"channel",offer.at("kind")},{"orderId",o.at("id")},{"carId",car.at("id")},{"city",cities.at(o.at("cityId").get<std::string>()).value("name","")},{"createdAt",o.at("createdAt")},{"signedAt",o.at("createdAt")},{"price",total},{"purchasePrice",total},{"vehicle",nativeCommerceVehicleDocuments(s,car,offers,home)},{"seller",seller},{"buyer",o.at("buyer")},{"costBreakdown",costs},{"paidAtSigning",paid},{"terms",terms}};if(recovered)record["recoveredFromOrder"]=true;b["records"].insert(b["records"].begin(),record);while(b["records"].size()>100)b["records"].erase(b["records"].end()-1);return true;
}
inline bool restoreNativeSupplyContracts(Json& s,const Json& cities,const Json& cars,const Json& offers,const std::string& home){if(s.value("supplyContractsVersion",0)>=1)return false;for(auto it=s["commerce"]["orders"].rbegin();it!=s["commerce"]["orders"].rend();++it){auto id=it->value("offerId","");if(!offers.contains(id))continue;const auto& offer=offers.at(id);auto key=std::to_string(offer.at("carId").get<Money>());if(cars.contains(key))appendNativeSupplyContract(s,*it,offer,cars.at(key),cities,offers,home,true);}s["supplyContractsVersion"]=1;return true;}
}
